const started = await tour.startWorkflow('add-google-drive-folder');
let status = await tour.showNextWorkflowStep(started.sessionId);
console.log(status);

while (status.status === 'waiting') {
  const next = await tour.continueWorkflow({
    sessionId: status.sessionId,
    afterRevision: status.revision,
    timeoutMs: 60000,
  });
  console.log(next);
  if (next.timedOut) break;
  status = next;
}
